/**
 * Riverside Regional Hospital: signed clinical documents.
 *
 * One item per signed document: an emergency department provider note, an admission history and
 * physical (H&P), a daily progress note, a specialty consult, or a discharge summary. Several documents
 * usually belong to one hospital encounter; the `encounter` entry in each item says which.
 *
 * The narrative is the note text the clinician signed. The payload holds the structured parts of the
 * note as the hospital EHR stored them when the note was signed: the encounter context, diagnoses, the
 * home medication list, inpatient medications, allergies, vital signs, and copies of lab results the
 * author reviewed.
 *
 * Read these before mapping:
 *
 * - **Every document re-lists the home medications and allergies.** Each list is a snapshot taken when
 *   that document was signed, with that document's status for each drug. Five documents in one stay
 *   mean five copies of the same drugs. For the hospital's final word on outpatient medications, use the
 *   most recent `discharge_summary` of the encounter.
 * - **Lab results are copies.** Riverside does not publish lab results as items of their own. A result
 *   appears inside whichever documents reviewed it, so the same result can appear in several items. The
 *   `accession` plus test code identifies one result across documents.
 * - **Lab values are text**, exactly as the lab displayed them: `"182"`, `"7.21"`, `"<0.01"`.
 * - **Payload times are UTC** (`Z`). Riverside is in America/Chicago (UTC-6 standard, UTC-5 daylight
 *   time). The clinical date of an evening visit is the local date, which can be a day earlier than the
 *   UTC date. Times written in the narrative are local wall-clock times.
 * - **No allergy/intolerance distinction.** Everything on the hospital's allergy list is an `allergy`
 *   entry, including side effects such as cough.
 *
 * Envelope conventions: `effective` is the time the document is about (ED arrival for an ED note, time
 * of examination for an H&P, progress note or consult, inpatient admission time for a discharge
 * summary, with `effective_end` = discharge time). `author` is the signing clinician. A signed addendum
 * or correction is a new item that `supersedes` the original and restates the whole document.
 */

/** One entry in a Riverside document payload. Discriminated by `type`. */
export type RiversideEntry =
  | Encounter
  | Diagnosis
  | History
  | Allergy
  | HomeMed
  | InpatientMed
  | Vitals
  | Result
  | Panel
  | FollowUp;

/**
 * The encounter and document context. Exactly one per item, conventionally under the key `enc`.
 */
export interface Encounter {
  type: 'encounter';

  /**
   * Riverside encounter number. One number covers the whole hospital stay, from ED arrival to
   * discharge: the ED note, H&P, progress notes, consults and discharge summary of one stay share it.
   */
  encounter_id: string;

  /**
   * Which kind of document this item is.
   * - 'ed_note': emergency department provider note.
   * - 'hp': admission history and physical, written by the admitting physician.
   * - 'progress_note': daily inpatient note.
   * - 'consult': note from a specialty service asked to see the patient.
   * - 'discharge_summary': written at discharge; covers the whole stay. Its home medication list is
   *   the discharge instructions.
   */
  document_kind: 'ed_note' | 'hp' | 'progress_note' | 'consult' | 'discharge_summary';

  /**
   * Encounter class at the time the document was signed.
   * - 'emergency': the patient was in the ED and not yet admitted.
   * - 'inpatient': admitted (including step-down and ICU).
   * A stay that starts in the ED changes class from 'emergency' to 'inpatient' at admission; earlier
   * documents keep the class they were signed with.
   */
  class: 'emergency' | 'inpatient';

  /** Clinical service of the author, free text as configured at Riverside, e.g. "Emergency Medicine", "Hospital Medicine", "Endocrinology". */
  service: string;

  /** ED arrival time, UTC. Present on every document of a stay that began in the ED. */
  arrived?: string;

  /** Inpatient admission order time, UTC. Absent while the patient is still in the ED. */
  admitted?: string;

  /** Discharge time, UTC. Present only on discharge summaries. */
  discharged?: string;

  /**
   * Where the patient went at the end of this phase of care.
   * - 'admitted': ED patient admitted to Riverside (ED notes only).
   * - 'home': discharged home without services.
   * - 'home_with_services': discharged home with home health.
   * - 'transferred': sent to another hospital.
   * - 'left_against_advice': left before the care team discharged them.
   * Absent on H&Ps, progress notes and consults.
   */
  disposition?: 'admitted' | 'home' | 'home_with_services' | 'transferred' | 'left_against_advice';
}

/**
 * A diagnosis on this document's diagnosis list, as the author left it at signing. Diagnoses are
 * re-entered in each document, so the same condition can appear in several items of one stay with
 * different statuses as the workup progresses.
 */
export interface Diagnosis {
  type: 'diagnosis';

  /** Diagnosis as the clinician wrote it, e.g. "R/O pancreatitis", "Euglycemic DKA, SGLT2 inhibitor-associated". */
  label: string;

  /**
   * ICD-10-CM code chosen by the author or added by coding. Absent on working diagnoses entered as free
   * text. An adverse drug effect is coded as its own diagnosis (an ICD-10-CM T-code), not as an
   * allergy.
   */
  icd10cm?: string;

  /**
   * Riverside local diagnosis code, used where ICD-10-CM is too coarse (for example to separate
   * SGLT2 inhibitor-associated euglycemic DKA from other DKA, which share ICD-10-CM E11.10). Code
   * space: Riverside problem dictionary, `RRH-DX-` followed by digits; stable across years.
   */
  riverside_dx?: { code: string; name: string };

  /**
   * Where the diagnosis stood when the document was signed.
   * - 'working': suspected and under evaluation, not established. A later document may confirm it,
   *   rule it out, or silently drop it; an absent later mention does not mean it was confirmed.
   * - 'ruled_out': considered and excluded. The patient does NOT have this condition.
   * - 'active': established and present.
   * - 'resolved': established during this stay and no longer present at signing (e.g. a ketoacidosis
   *   that cleared). The patient had it.
   */
  status: 'working' | 'ruled_out' | 'active' | 'resolved';

  /**
   * - 'principal': the main reason for the hospital stay. Set on H&Ps and discharge summaries only.
   * - 'secondary': any other diagnosis addressed in this document.
   * Absent on ED notes, which do not rank diagnoses.
   */
  rank?: 'principal' | 'secondary';
}

/**
 * A line of past medical history as recorded in this document. Taken from the patient, outside
 * records, or earlier Riverside documents, and not re-verified: stages and dates can be out of date.
 */
export interface History {
  type: 'history';

  /** Condition as written, e.g. "CKD stage 3a", "Type 2 diabetes". */
  condition: string;

  /** ICD-10-CM code if the author picked one from the problem dictionary; often absent. */
  icd10cm?: string;

  /** Onset as written, free text and not normalized: "2016", "~10 years", "childhood". Absent if not stated. */
  onset_text?: string;

  /**
   * Where the line came from.
   * - 'patient': patient or family report.
   * - 'outside_records': another organization's records (e.g. a primary care summary).
   * - 'riverside': an earlier Riverside document.
   */
  source: 'patient' | 'outside_records' | 'riverside';
}

/**
 * An entry on Riverside's allergy list as shown in this document. Riverside keeps one list called
 * "Allergies" and does not separate allergies from intolerances or side effects: a drug that once
 * caused a cough is listed the same way as one that caused anaphylaxis. Read `reaction` to tell them
 * apart. Re-listed in every document.
 */
export interface Allergy {
  type: 'allergy';

  /**
   * Substance as entered, e.g. "lisinopril", "penicillins". If the patient has no known allergies, the
   * list has exactly one entry with substance "NKDA" and no other fields.
   */
  substance: string;

  /** RxNorm ingredient CUI when the substance is a single drug ingredient; absent for classes, foods and "NKDA". */
  rxnorm_ingredient?: string;

  /** Reaction as entered, free text, e.g. "cough", "hives". Absent if unknown. */
  reaction?: string;

  /**
   * Severity as entered.
   * - 'mild': bothersome, not dangerous.
   * - 'moderate': needed treatment or stopping the drug urgently.
   * - 'severe': life-threatening (e.g. anaphylaxis, angioedema).
   * - 'unknown': not recorded.
   */
  severity: 'mild' | 'moderate' | 'severe' | 'unknown';
}

/**
 * One line of the home (outpatient) medication list, with this document's decision about it.
 *
 * The meaning of `status` depends on `document_kind` in the item's `encounter` entry:
 * in ED notes, H&Ps, progress notes and consults it is the plan **during the stay**; in a discharge
 * summary it is the instruction **after discharge**. Only the latest discharge summary of an encounter
 * says what the patient should take at home.
 *
 * Entry keys are chosen per document. They often repeat across the documents of a stay (`med_empa`),
 * but nothing guarantees it: match lines across documents by `rxnorm_ingredient` and `dose_text`, never
 * by key.
 */
export interface HomeMed {
  type: 'home_med';

  /** Drug and form as written on the list, e.g. "empagliflozin 10 mg tablet". */
  drug_name: string;

  /**
   * RxNorm ingredient CUI (not a clinical drug code: strength and form are in `drug_name` and
   * `dose_text`). Absent for combination products and supplements that are not mapped.
   */
  rxnorm_ingredient?: string;

  /** Dose per administration as written, e.g. "1000 mg", "10 units". Text, not normalized. */
  dose_text: string;

  /** Directions as written, e.g. "1 tab PO BID with meals". Not normalized. */
  sig: string;

  /**
   * This document's decision for the drug (see the interface comment for during-stay vs after-discharge).
   * - 'not_reconciled': listed from the patient or prior records; the author made no decision. Typical
   *   of ED notes. Does not mean the patient is taking it now.
   * - 'continue': keep taking (or keep giving in hospital). In a discharge summary this includes a drug
   *   that was held during the stay and is restarted at discharge.
   * - 'held': do not take for now. Not stopped: someone decides later whether to restart, and
   *   `restart_advice` says which way this author leans. `instructions` usually says who decides and
   *   when.
   * - 'stopped': discontinued by this author.
   * - 'new': started during this stay, to continue.
   * - 'changed': same drug, new dose or directions; `dose_text`/`sig` show the new ones.
   */
  status: 'not_reconciled' | 'continue' | 'held' | 'stopped' | 'new' | 'changed';

  /**
   * On 'held' lines only: what this author advises about restarting. Absent on other statuses, and on
   * held lines where the author gave no advice.
   * - 'resume_when_able': restart once the reason for holding has passed (eating again, creatinine back
   *   to baseline). `instructions` usually names the condition.
   * - 'prescriber_decides': no advice either way; the outpatient prescriber decides.
   * - 'advise_against': the author recommends not restarting. The line is held rather than stopped
   *   because the outpatient prescriber makes the final decision. The patient is not taking the drug.
   */
  restart_advice?: 'resume_when_able' | 'prescriber_decides' | 'advise_against';

  /** Free-text instruction attached to the status, e.g. "Do not resume until reviewed by PCP". Absent if none. */
  instructions?: string;
}

/**
 * A medication ordered for use in the hospital only (infusions, IV fluids, inpatient-only drugs).
 * Not part of the home list and not continued after discharge unless it also appears there as 'new'.
 */
export interface InpatientMed {
  type: 'inpatient_med';

  /** Drug or fluid as ordered, e.g. "insulin regular (human) IV infusion", "lactated Ringer's". */
  drug_name: string;

  /** RxNorm ingredient CUI; absent for IV fluids and mixtures. */
  rxnorm_ingredient?: string;

  /** Route as ordered, e.g. "IV", "SubQ", "PO". */
  route: string;

  /** Dose or rate as ordered, free text, e.g. "per DKA protocol, 0.1 units/kg/h", "150 mL/h". */
  dose_text: string;

  /** First administration, UTC. */
  started: string;

  /** Last administration or order discontinue time, UTC. Absent if still running when the document was signed. */
  stopped?: string;
}

/** One set of vital signs taken at one time. Any member may be absent if not measured. */
export interface Vitals {
  type: 'vitals';

  /** When the vitals were taken, UTC. */
  taken: string;

  /** Blood pressure in mmHg. */
  bp?: { systolic_mmhg: number; diastolic_mmhg: number };

  /** Heart rate, beats per minute. */
  heart_rate_bpm?: number;

  /** Respiratory rate, breaths per minute. */
  resp_rate_per_min?: number;

  /** Temperature in degrees Fahrenheit, as entered by nursing. */
  temp_f?: number;

  /** Oxygen saturation by pulse oximetry, percent (0–100). */
  spo2_pct?: number;

  /** Weight in kilograms (converted by the EHR from whatever unit was entered). */
  weight_kg?: number;
}

/**
 * The value part of a lab result. Used on its own as `Result` and for each component of a `Panel`.
 */
export interface ResultValue {
  /**
   * Riverside lab test. `local_code` is the Riverside lab dictionary code (stable across years).
   * `loinc` is present for most chemistry and hematology tests and absent for some point-of-care and
   * send-out tests (e.g. beta-hydroxybutyrate). `name` is the display name.
   */
  test: { local_code: string; loinc?: string; name: string };

  /**
   * Result exactly as displayed by the lab, as text. Usually a decimal number (`"182"`, `"7.21"`), but
   * may carry a comparator (`"<0.01"`, `">600"`) or be words (`"Hemolyzed, see comment"`). Parse with
   * care; a comparator means the true value is beyond the reportable limit.
   */
  value: string;

  /**
   * Unit as the lab reports it, close to UCUM: "mg/dL", "mmol/L", "U/L", "ng/mL", "10*3/uL" (thousands
   * per microliter), "g/dL", "mmHg", "mL/min/1.73m2". Absent for unitless results (pH).
   */
  unit?: string;

  /** Reference range as displayed, text, in the same unit as `value`, e.g. "70-99", "<0.04". Absent if the lab gives none. */
  ref_range?: string;

  /**
   * Abnormal flag from the lab.
   * - 'H' / 'L': above / below the reference range.
   * - 'HH' / 'LL': critically high / low.
   * - 'A': abnormal, no direction (non-numeric results).
   * Absent when the value is within range.
   */
  flag?: 'H' | 'L' | 'HH' | 'LL' | 'A';
}

/**
 * Copy of one lab result reviewed in this document. The same result (same `accession` and
 * `test.local_code`) can appear in several documents; it is one result, not several.
 */
export interface Result extends ResultValue {
  type: 'result';

  /** Riverside lab accession number for the specimen. With `test.local_code` it identifies the result. */
  accession: string;

  /** Specimen collection time, UTC. */
  collected: string;

  /** Specimen as labelled by the lab, e.g. "serum", "venous blood", "whole blood". */
  specimen: string;

  /**
   * Status of the result when this document copied it.
   * - 'preliminary': reported but not verified; may change.
   * - 'final': verified.
   * - 'corrected': a final value that the lab later changed; `value` is the corrected value.
   * A document never updates after signing, so a later document can show a different status or value
   * for the same result. Use the copy with the most advanced status.
   */
  status: 'preliminary' | 'final' | 'corrected';
}

/**
 * Copy of a panel of results from one specimen (basic metabolic panel, CBC, blood gas). Components carry
 * their own codes, values and flags; the panel carries what they share. Same duplication rules as
 * `Result`.
 */
export interface Panel {
  type: 'panel';

  /** Riverside panel order code and name, e.g. { local_code: "BMP", name: "Basic metabolic panel" }. LOINC present when the panel has one. */
  panel: { local_code: string; loinc?: string; name: string };

  /** Riverside lab accession number for the specimen. */
  accession: string;

  /** Specimen collection time, UTC. */
  collected: string;

  /** Specimen as labelled by the lab, e.g. "serum", "venous blood", "whole blood". */
  specimen: string;

  /** Status of the panel as a whole when copied; same values and meaning as `Result.status`. */
  status: 'preliminary' | 'final' | 'corrected';

  /**
   * Component results, in the lab's display order. Includes computed values the lab reports with the
   * panel (anion gap, eGFR). eGFR at Riverside is CKD-EPI 2021 (race-free) for all results since 2023.
   */
  components: ResultValue[];
}

/** A follow-up the author arranged or recommended. Mostly in discharge summaries. */
export interface FollowUp {
  type: 'follow_up';

  /** Clinician, clinic or service to follow up with, as written, e.g. "Primary care (Northgate Family Medicine)". */
  with: string;

  /** When, as written, e.g. "within 1 week", "2024-11-12". Not normalized. */
  when_text: string;

  /** What the follow-up is for, free text. */
  purpose: string;
}

/**
 * Consumer views, version 1: the small shapes a patient-facing chart app reads.
 *
 * These are defined by the consumer, not by any source. A mapper turns one source's FOLIO record items
 * for one patient into these rows. The consumer merges rows from several sources itself, so a mapper
 * reports only what its own source says, and never invents, infers from other sources, or "corrects"
 * what the source records.
 *
 * Contract (see `Transform`): the mapper receives every item one source published for one patient,
 * in no particular order and including items that were later superseded or retracted, plus an
 * `asOf` date. It returns the rows that describe that source's record as it stood at the end of that
 * date.
 *
 * Conventions for every view:
 *
 * - **Scope in time.** An item is in scope when its envelope `recorded` time is on or before the end of
 *   the `asOf` day in America/Chicago. Ignore items recorded later. Apply the FOLIO correction rules to
 *   the items in scope: an item listed in another in-scope item's `supersedes` or `retracts` (same
 *   issuer) is not current; supersession is transitive. Use only current items, except where a view
 *   below says otherwise.
 * - **Time zone.** The consumer displays everything in America/Chicago. "Local date" and "local time"
 *   below mean wall-clock date/time in America/Chicago (UTC-6 standard, UTC-5 daylight time).
 * - **Partial dates.** `PartialDate` strings keep the precision the source actually knows: "2016"
 *   means some time in 2016, never 2016-01-01. Never pad a year-only or month-only date.
 * - **Only what the source records.** Rows come from structured payload entries. Narrative text may be
 *   used to understand an entry but must not be the only basis for a row.
 * - **Evidence.** Every row lists the items (and payload entry ids) it was built from, so the consumer
 *   can show the source text behind a fact.
 * - **Determinism.** Same input, same output: no clock, randomness, network or file access.
 */

/** A FOLIO record item in its JSON form (see the FOLIO record-item spec). */
export interface FolioItem {
  folio: string;
  /** Item id (ULID), unique within the issuer. */
  id: string;
  /** did:web of the issuing organization. */
  issuer: string;
  /** Patient id at this issuer. */
  patient: string;
  /** When the clinical event happened: RFC 3339 date-time with offset, or a full or partial date. */
  effective: string;
  effective_end?: string;
  /** When the issuer committed this item: RFC 3339 date-time with offset. */
  recorded: string;
  author?: { id?: string; name?: string; role?: string };
  /** The payload's schema: `type` names the entry type in the source's .d.ts. */
  schema?: { url: string; type: string; sha256: string };
  /** Ids of earlier items from the same issuer that this item replaces entirely. */
  supersedes?: string[];
  /** Ids of earlier items from the same issuer that were entered in error, withdrawn without replacement. */
  retracts?: string[];
  /** Markdown narrative with `<ref id="…">…</ref>` spans; "" if none. */
  narrative: string;
  /** Entry id -> entry, each entry typed by the source's schema; {} if none. */
  payload: Record<string, any>;
}

/** The mapper's entry point. `asOf` is a local date, `YYYY-MM-DD`. */
export type Transform = (items: FolioItem[], asOf: string) => ViewRows;

/** Everything one mapper returns for one patient and one source. Empty arrays where the source has nothing. */
export interface ViewRows {
  medications: MedicationRow[];
  problems: ProblemRow[];
  allergies: AllergyIntoleranceRow[];
  labs: LabResultRow[];
  vitals: VitalRow[];
}

/** `YYYY`, `YYYY-MM` or `YYYY-MM-DD`; the precision is the string's length. */
export type PartialDate = string;

/** The items (and entries inside them) a row was built from. At least one. */
export type Evidence = { item_id: string; entry_id?: string }[];

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Medications
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One outpatient (home) medication as this source records it, with its status as of `asOf`.
 *
 * - One row per drug ingredient. If the source has several lines, orders or prescriptions for the
 *   same ingredient over time (stopped and restarted, re-entered), report the most recent one, i.e.
 *   the one whose own latest event is latest. A line or order that was entered in error, voided or
 *   retracted never existed: do not report it, and do not let it affect another line.
 * - Include medications that are stopped (status 'stopped') if the source still shows them, so the
 *   consumer can say what was stopped and why.
 * - Exclude hospital-only orders (infusions, IV fluids, inpatient-only drugs). They are not home
 *   medications.
 * - When the source publishes a medication list as repeated snapshots (each document or save restates
 *   the list), the latest in-scope snapshot is the source's list; a drug missing from the latest
 *   snapshot is not reported. When the source publishes events or status rows, the latest event or
 *   status row for a line determines its state, however old it is.
 */
export interface MedicationRow {
  /**
   * Generic ingredient name, lower case, without salt or form: "losartan" (not "losartan potassium"),
   * "metformin", "insulin glargine", "empagliflozin". Translate brand names the record uses
   * ("Jardiance" -> "empagliflozin"). Omit only when the record does not say which drug it is (e.g. the
   * patient wrote "water pill").
   */
  ingredient?: string;
  /** RxNorm ingredient CUI, only when the source states an ingredient-level RxNorm code. Never guessed or derived from a product code. */
  rxnorm_ingredient?: string;
  /** The drug as the source names it (display text), e.g. "losartan potassium 50 MG Oral Tablet" or "Jardiance". */
  drug_name: string;
  /**
   * Status as of `asOf`, by this source's account.
   * - 'active': the patient should be taking it (or, on a patient's own list, says they are).
   * - 'held': paused with intent (or at least possibility) of resuming; the patient should not be
   *   taking it now. Not the same as stopped.
   * - 'stopped': discontinued.
   * - 'unknown': the source lists the drug but records no decision about whether it is being taken
   *   (e.g. a hospital list marked as not reconciled).
   */
  status: 'active' | 'held' | 'stopped' | 'unknown';
  /**
   * Local date on which the current status began according to this source: for 'held' or 'stopped',
   * the date of the hold or stop; for 'active', the date the source's current line or order started
   * (or resumed). Keep the source's precision. Omit if the source does not say.
   */
  status_since?: PartialDate;
  /**
   * Amount per administration currently prescribed (for 'held' and 'stopped': the amount when it was
   * held or stopped). For a patient's own list: the amount the patient says they take, if they give
   * one. `unit` is one of the listed units; convert source spellings ("unit", "UNT", "[iU]" ->
   * "units"; "tab"/"tablets" -> "tablet"). Omit when the source gives no single amount.
   */
  dose?: { value: number; unit: 'mg' | 'mcg' | 'units' | 'mL' | 'tablet' };
  /**
   * How often, normalized: 'QD' once daily, 'BID' twice daily, 'TID' three times daily, 'QHS' once
   * daily at bedtime, 'QW' once weekly, 'PRN' as needed, 'other' anything else. Omit if unknown.
   */
  frequency?: 'QD' | 'BID' | 'TID' | 'QHS' | 'QW' | 'PRN' | 'other';
  /**
   * For 'stopped' rows, why, when the source records a coded or clearly stated reason:
   * - 'adverse_reaction': side effect or adverse reaction.
   * - 'ineffective': not working well enough.
   * - 'therapy_changed': replaced by another drug for the same purpose.
   * - 'course_complete': finite course finished.
   * - 'patient_choice': the patient declined or asked to stop.
   * - 'other': another reason (see `status_reason_text`).
   * Omit when the source gives no reason, and on rows that are not 'stopped'.
   */
  stop_reason?: 'adverse_reaction' | 'ineffective' | 'therapy_changed' | 'course_complete' | 'patient_choice' | 'other';
  /** Free-text reason for the current status (hold or stop) as the source wrote it, if any. */
  status_reason_text?: string;
  /** True when the row comes from the patient's own account (a self-reported list), not a clinician's record. */
  patient_reported: boolean;
  /** True when the source says the drug was bought without a prescription. Omit otherwise. */
  otc?: boolean;
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Problems
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One condition on the source's problem list (or the source's equivalent: its diagnosis or history
 * lists), with status as of `asOf`.
 *
 * - One row per condition. Several entries for the same condition (re-listed in several documents,
 *   restaged, re-coded) are one row whose fields reflect the latest entry.
 * - Report only conditions the source asserts the patient has or had. Never report a condition that
 *   was ruled out, or one that was only suspected (working/provisional) and never confirmed.
 * - Billing codes attached to a visit or claim are not problem-list entries, unless the source says
 *   its problem list is built from them.
 * - An adverse effect of a drug (however the source records it, including as an ICD-10 T-code
 *   diagnosis) is an `AllergyIntoleranceRow` of type 'adverse_reaction', not a problem. The illness it
 *   caused (e.g. ketoacidosis) is still a problem.
 */
export interface ProblemRow {
  /** The condition as the source words it, e.g. "Chronic kidney disease stage 3a". */
  condition: string;
  /** ICD-10-CM code, with the dot, as the source gives it (latest). Omit if the source gives none. */
  icd10cm?: string;
  /** SNOMED CT concept id, if the source gives one. */
  snomed?: string;
  /**
   * - 'active': the patient has it.
   * - 'resolved': the patient had it and the source says it is resolved or historical.
   */
  status: 'active' | 'resolved';
  /** When the condition began, at the precision the source knows. Omit if the source does not say. */
  onset?: { value: PartialDate; precision: 'year' | 'month' | 'day' };
  /**
   * For chronic kidney disease only: the KDIGO GFR category the source most recently recorded for this
   * patient ('G3a' for "stage 3a", "N18.31" or a G3a category field). As recorded by a clinician; never
   * computed from lab values.
   */
  ckd_stage?: 'G1' | 'G2' | 'G3a' | 'G3b' | 'G4' | 'G5';
  /** For chronic kidney disease only: KDIGO albuminuria category as recorded ('A1', 'A2', 'A3'), if the source records one. */
  albuminuria?: 'A1' | 'A2' | 'A3';
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Allergies, intolerances, adverse reactions
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One substance the patient should avoid or be careful with, as of `asOf`. Only current entries: an
 * entry the source marks inactive or invalid is not reported. "No known drug allergies" is not a row.
 */
export interface AllergyIntoleranceRow {
  /** Substance: generic ingredient name, lower case, for drugs ("lisinopril"); as written otherwise. */
  substance: string;
  /** RxNorm ingredient CUI, if the source gives one. */
  rxnorm_ingredient?: string;
  /**
   * What kind of reaction, by its nature (not by which list the source keeps it on):
   * - 'allergy': immune-mediated (hives, rash, angioedema, anaphylaxis, bronchospasm).
   * - 'intolerance': a non-immune, predictable side effect that made the drug unacceptable (e.g.
   *   ACE-inhibitor cough, GI upset).
   * - 'adverse_reaction': a serious harmful event attributed to the drug that is not an allergy (e.g.
   *   drug-associated ketoacidosis, lactic acidosis).
   * If the source keeps all three on one undifferentiated list, decide from the recorded reaction.
   */
  type: 'allergy' | 'intolerance' | 'adverse_reaction';
  /** Reaction(s) as the source words them, joined with "; ". Omit if not recorded. */
  reaction?: string;
  /**
   * Criticality: how dangerous re-exposure is judged to be.
   * - 'high': re-exposure could be serious or life-threatening.
   * - 'low': re-exposure unlikely to cause serious harm.
   * - 'unknown': not assessed or not derivable.
   * A source's "severity" scale is mapped by meaning: mild -> 'low'; severe or life-threatening -> 'high'.
   */
  criticality: 'low' | 'high' | 'unknown';
  /** When the reaction began, at the precision the source knows. */
  onset?: { value: PartialDate; precision: 'year' | 'month' | 'day' };
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Lab results
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Analytes this consumer tracks, with the unit `LabResultRow.value` must be in. Results for other
 * tests are not reported.
 *
 * | analyte         | unit            | notes |
 * |-----------------|-----------------|-------|
 * | creatinine      | mg/dL           | serum |
 * | egfr            | mL/min/1.73m2   | see `egfr_equation` and the eGFR rule below |
 * | potassium       | mmol/L          | |
 * | sodium          | mmol/L          | |
 * | chloride        | mmol/L          | |
 * | bicarbonate     | mmol/L          | total CO2 |
 * | anion_gap       | mmol/L          | |
 * | bun             | mg/dL           | urea nitrogen |
 * | glucose         | mg/dL           | laboratory glucose (serum/plasma); home meter readings are vitals |
 * | a1c             | %               | NGSP |
 * | uacr            | mg/g            | urine albumin/creatinine ratio |
 * | platelets       | 10*3/uL         | thousands per microlitre: 212 000 cells/uL is 212 |
 * | wbc             | 10*3/uL         | thousands per microlitre |
 * | hemoglobin      | g/dL            | |
 * | bhb             | mmol/L          | beta-hydroxybutyrate |
 * | ph              | [pH]            | blood gas pH |
 * | pco2            | mmHg            | |
 * | lipase          | U/L             | |
 * | troponin        | ng/mL           | troponin I |
 * | cholesterol     | mg/dL           | total |
 * | triglycerides   | mg/dL           | |
 * | hdl             | mg/dL           | |
 * | ldl             | mg/dL           | measured or calculated |
 */
export type Analyte =
  | 'creatinine' | 'egfr' | 'potassium' | 'sodium' | 'chloride' | 'bicarbonate' | 'anion_gap' | 'bun'
  | 'glucose' | 'a1c' | 'uacr' | 'platelets' | 'wbc' | 'hemoglobin' | 'bhb' | 'ph' | 'pco2' | 'lipase'
  | 'troponin' | 'cholesterol' | 'triglycerides' | 'hdl' | 'ldl';

/**
 * One valid laboratory result.
 *
 * - One row per result. A result the source shows several times (copies in several documents, a
 *   preliminary and a final copy) is one row, taken from the copy with the most advanced status.
 * - Report only values that stand: leave out results that were withdrawn, invalidated or "corrected
 *   away" by the lab, results of orders voided or entered in error, results not performed, and
 *   superseded copies. A confirmation repeat is a second valid result; keep both.
 * - **eGFR rule.** One eGFR row per eGFR calculation the source reports for a specimen. When the source
 *   reports race-specific variants of one calculation (a value with and one without a race
 *   coefficient), report only the variant without the race coefficient. Report the value as printed
 *   (do not recompute).
 */
export interface LabResultRow {
  analyte: Analyte;
  /** Numeric value in the analyte's unit (see `Analyte`). For a result printed with a comparator (">60", "<0.01"), the number part. */
  value: number;
  /** Set when the printed result has a comparator: ">60" -> value 60, comparator '>'. */
  comparator?: '<' | '>' | '<=' | '>=';
  /** The analyte's unit from the table in `Analyte`, exactly as written there. */
  unit: string;
  /** Specimen collection time, RFC 3339 with offset (any offset; it denotes an instant). */
  collected: string;
  /** 'final' (also for amended or corrected values that stand) or 'preliminary'. */
  status: 'final' | 'preliminary';
  /**
   * For analyte 'egfr' only: the equation the source says it used.
   * - 'ckd-epi-2021': CKD-EPI 2021 (race-free).
   * - 'ckd-epi-2009': CKD-EPI 2009.
   * - 'mdrd': MDRD.
   * - 'unknown': not stated.
   * When a code and a method note disagree, believe the method note.
   */
  egfr_equation?: 'ckd-epi-2021' | 'ckd-epi-2009' | 'mdrd' | 'unknown';
  /** LOINC code if the source gives one for this result. */
  loinc?: string;
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Vital signs and home readings
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One set of vital signs taken together, or one home reading.
 *
 * - A clinic or hospital vital-sign set (BP, pulse, weight taken within a few minutes at one visit) is
 *   one row; `local_time` is the time of its first blood pressure (or of its first measurement if no
 *   BP). A repeat blood pressure taken later in the same visit goes in `repeat_*` on the same row.
 * - Each home BP reading and each home glucose reading is its own row.
 * - Each measurement is reported once: if a source shows the same measurement twice (a reading typed
 *   in by hand that duplicates one synced from the device a minute or two earlier with the same
 *   values), report it once, preferring the device copy.
 */
export interface VitalRow {
  /** 'clinic' (outpatient office), 'hospital' (ED or inpatient), or 'home' (patient's own devices). */
  setting: 'clinic' | 'hospital' | 'home';
  /** Local wall-clock time in America/Chicago, `YYYY-MM-DDTHH:MM`. */
  local_time: string;
  systolic_mmhg?: number;
  diastolic_mmhg?: number;
  /** Repeat blood pressure at the same visit, if one was taken. */
  repeat_systolic_mmhg?: number;
  repeat_diastolic_mmhg?: number;
  pulse_bpm?: number;
  /** Body weight in kilograms (1 lb = 0.45359237 kg), one decimal place. */
  weight_kg?: number;
  /** Home glucose meter reading in mg/dL (1 mmol/L = 18.016 mg/dL), rounded to a whole number. */
  glucose_mg_dl?: number;
  /** Set when the meter showed HI or LO instead of a number; `glucose_mg_dl` is then the meter's limit in mg/dL. */
  glucose_out_of_range?: 'HI' | 'LO';
  evidence: Evidence;
}

