  PLT: "platelets", WBC: "wbc", HGB: "hemoglobin", HB: "hemoglobin",
  BHB: "bhb", VPH: "ph", APH: "ph", PH: "ph", CPH: "ph", VPCO2: "pco2", APCO2: "pco2", PCO2: "pco2", CPCO2: "pco2",
  LIPASE: "lipase", LIP: "lipase", TROPI: "troponin", TNI: "troponin", TROP: "troponin",
